      "worker": "A1",
      "task": "Write a 150-word product description for each of the 12 items using ONLY names and attributes from A2's output.",
      "why": "A1 is fast and fluent; it can generate volume quickly as long as its input is strictly bounded."
    },
    {
      "step": 3,
      "worker": "A2",
      "task": "Validate that each description contains no price/stock claims not present in the original CSV.",
      "why": "A2's strength is structured verification; it can cross-check text against numeric fields without needing internet or dashboards."
    },
    {
      "step": 4,
      "worker": "A3",
      "task": "Run a full false-claim audit on all 12 pages (description + price/stock). Flag any deviation from source data.",
      "why": "Only A3 has proven ability to catch planted or subtle errors; this is the single gatekeeper against refunds."
    },
    {
      "step": 5,
      "worker": "A4",
      "task": "Push validated pages to staging URLs in alphabetical order by product_id.",
      "why": "A4 executes exact instructions without deviation; it is ideal for deterministic deployment once content is locked."
